inline double normalize_arc_sweep(double start_angle, double end_angle, bool anticlockwise) {
  double sweep = (end_angle - start_angle);
  if (anticlockwise) {
    if ((sweep > 0.0)) {
      (sweep -= (flight::pi * 2.0));
    }
  }
  else {
    if ((sweep < 0.0)) {
      (sweep += (flight::pi * 2.0));
    }
  }
  return sweep;
}

